import {jsonStore,failure,identity} from '../official/store.mjs';
import {READER_PLUGIN,globalSpeechSource,speechCapabilities,speechParameters,readingParagraphs,readableDocument} from '../ui/speech-contract.js';
import {createSpeechEngine,inspectWav,inspectSpeechRuntime,prepareSystemVoices} from './speech-engine.mjs';
import {createReaderLibrary,readerVersion} from './reader-library.mjs';
import {createPollyClient,pollyConnection,pollyCredentials} from './aws-polly.mjs';
